import React from 'react';

import { HikingContext } from '@apps/Hiking/@contexts/hikingContext';
import { getHikingDaysData } from '@apps/Hiking/@helpers/hikingDays.helper';
import { getHikingJointlyEquipments } from '@apps/Hiking/@services/hikingJointlyEquipment.service';
import { getHikingTransfers } from '@apps/Hiking/@services/hikingTransfers.service';
import { IHikingJointlyEquipment } from '@apps/Hiking/@types/hikingJointlyEquipment.types';
import { IHikingTransfer } from '@apps/Hiking/@types/hikingTransfers.types';
import A4Page, { A4SubPage } from '@components/A4Page';
import PageLoader from '@components/PageLoader';
import PolylineInfo from '@components/PolylineInfo';
import { formattedLocaleTime } from '@helpers/dateHelper';
import { formatDistance } from '@helpers/formatHelper';
import { err } from '@helpers/notificationHelper';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';

import HikingPrintDuty from './components/HikingPrintDuty';
import HikingPrintFood from './components/HikingPrintFood';
import HikingPrintSchedule from './components/HikingPrintSchedule';
import HikingPrintTransfers from './components/HikingPrintTransfers';
import HikingPrintUsersLoad from './components/HikingPrintUsersLoad';
import HikingPrintWeather from './components/HikingPrintWeather';
import HikingPrintCommonEquipPage from './HikingPrintCommonEquipPage';
import HikingPrintFirstAidKit from './HikingPrintFirstAidKit';
import HikingPrintFrontPage from './HikingPrintFrontPage';
import HikingPrintJointlyEquipment from './HikingPrintJointlyEquipment';
import HikingPrintMembersPage from './HikingPrintMembersPage';
import HikingPrintPlanRouteDatesPage from './HikingPrintPlanRouteDatesPage';
import HikingPrintPlanRoutePage from './HikingPrintPlanRoutePage';
import HikingPrintRepairKit from './HikingPrintRepairKit';
import { weekDays } from '../../../../resources/dates';
import {
  getBaseRouteDataAsync,
  getRouteObjectsAsync,
} from '../../../Routes/@services/routes.service';
import {
  IBaseRouteObjectLine,
  IMapType,
  IRouteObject,
  RouteObjectType,
} from '../../../Routes/@types/routes.types';
import { getHikingEquip } from '../../@services/equip.service';
import { getHikingDataAsync } from '../../@services/hiking.service';
import { getHikingDuty } from '../../@services/hikingDuty.service';
import { getFoodAsync, getHikingMenuProductsAsync } from '../../@services/hikingMenu.service';
import { getHikingSchedule } from '../../@services/hikingSchedule.service';
import { getHikingWeather } from '../../@services/hikingWeather.service';
import { IHikingEquip } from '../../@types/equip.types';
import { IHikingDuty, IHikingScheduleItem } from '../../@types/hiking.baseTypes';
import { IHikingData } from '../../@types/hiking.types';
import { IHikingMenuExtendedProduct, IHikingMenuFood } from '../../@types/hikingMenu.types';
import { IHikingWeather } from '../../@types/hikingWeather.types';

interface IHikingPrintProps {
  id_hiking: number;
}

const HikingPrint: React.FC<IHikingPrintProps> = ({ id_hiking }) => {
  const [isLoading, setIsLoading] = React.useState<boolean>(true);
  const [hikingData, setHikingData] = React.useState<IHikingData>();
  const [hikingSchedule, setHikingSchedule] = React.useState<IHikingScheduleItem[]>([]);
  const [hikingFood, setHikingFood] = React.useState<IHikingMenuFood[]>([]);
  const [hikingDuty, setHikingDuty] = React.useState<IHikingDuty[]>([]);
  const [routeObjects, setRouteObjects] = React.useState<IRouteObject[]>([]);
  const [mapData, setMapData] = React.useState<IMapType>();
  const [hikingEquip, setHikingEquip] = React.useState<IHikingEquip[]>([]);
  const [jointlyEquipment, setJointlyEquipment] = React.useState<IHikingJointlyEquipment[]>([]);
  const [hikingTransfers, setHikingTransfers] = React.useState<IHikingTransfer[]>([]);

  const [products, setProducts] = React.useState<IHikingMenuExtendedProduct[]>([]);
  const [weather, setWeather] = React.useState<IHikingWeather[]>([]);

  React.useEffect(() => {
    const init = async () => {
      const hd = await getHikingDataAsync(id_hiking);
      setHikingData(hd);

      await getHikingSchedule(id_hiking).then(setHikingSchedule);
      await getHikingDuty(id_hiking).then(setHikingDuty);
      await getFoodAsync({ id_hiking }).then(setHikingFood);
      await getHikingMenuProductsAsync(id_hiking).then(setProducts);
      await getHikingEquip(id_hiking).then(setHikingEquip);
      await getHikingWeather(id_hiking).then(setWeather);
      await getHikingTransfers(id_hiking).then(setHikingTransfers);
      await getHikingJointlyEquipments(id_hiking).then(setJointlyEquipment);

      if (hd.route.id) {
        await getRouteObjectsAsync(hd.route.id).then(setRouteObjects);

        const brd = await getBaseRouteDataAsync(hd.route.id);
        setMapData(brd.typeData);
      }
    };

    init()
      .catch(err)
      .finally(() => setIsLoading(false));
  }, [id_hiking]);

  if (isLoading) {
    return <PageLoader />;
  }

  if (!hikingData) return <PohAlert variant={AlertVariant.Danger}>Has no hikingData</PohAlert>;

  if (!mapData) return <PohAlert variant={AlertVariant.Danger}>Has no mapData</PohAlert>;

  if (routeObjects.length === 0)
    return <PohAlert variant={AlertVariant.Warning}>Has no routeObjects</PohAlert>;

  if (!hikingFood) {
    return <PageLoader />;
  }

  const daysData = getHikingDaysData({
    hikingSchedule,
    hikingDuty,
    hikingTransfers,
    hikingFood,
    products,
    hikingData,
  });

  return (
    <HikingContext.Provider value={hikingData}>
      {/* <header className="d-print-none d-flex justify-content-center" style={{ gap: '8px' }}>
                header {hikingData.name}
            </header> */}

      <HikingPrintFrontPage />
      <HikingPrintMembersPage />
      <HikingPrintPlanRoutePage routeObjects={routeObjects} mapType={mapData} />
      <HikingPrintPlanRouteDatesPage routeObjects={routeObjects} daysData={daysData} />
      <A4Page>
        {daysData.map((dayData, i) => {
          const isMain =
            dayData.date.getTime() >= hikingData?.start.setHours(0, 0, 0, 0) &&
            dayData.date.getTime() <= hikingData?.finish.setHours(23, 59, 59, 999);

          const currentWeather = weather.find(
            (w) => w.date.toLocaleDateString() === dayData.date.toLocaleDateString(),
          );

          return (
            <A4SubPage key={dayData.date.toISOString()}>
              <h2 className="mt-5">
                День {i + 1}. {dayData.date.toLocaleDateString()}
                &nbsp;
                <small>{weekDays[dayData.date.getDay()]}</small>
                {isMain && (
                  <small className="text-success">
                    {' '}
                    {(dayData.date.getTime() - hikingData?.start.getTime()) / 1000 / 60 / 60 / 24 +
                      1}
                    -й ходовой
                  </small>
                )}
              </h2>
              {currentWeather && <HikingPrintWeather weather={currentWeather} className="mt-3" />}
              <PohRow className="mt-3">
                <PohCol sm={dayData.duty.length > 0 ? 8 : 12}>
                  <HikingPrintSchedule dayData={dayData} />
                </PohCol>

                {dayData.duty.length > 0 && (
                  <PohCol sm={4}>
                    <HikingPrintDuty dayData={dayData} />
                  </PohCol>
                )}
              </PohRow>

              {dayData.userLoad && <HikingPrintUsersLoad dayData={dayData} />}

              <HikingPrintFood
                dayData={dayData}
                hikingFood={hikingFood}
                hikingData={hikingData}
                products={products}
              />

              {dayData.schedules.some((sh) => sh.routeObject?.id) && (
                <A4SubPage>
                  <h3 className="mt-5">Передвижения</h3>
                  {dayData.schedules
                    .filter((sh) => sh.routeObject?.id && sh.routeObject.distance)
                    .map((sh, _i, allRo) => {
                      const routeObject = routeObjects.find(
                        (ro) => +ro.id === sh.routeObject!.id,
                      ) as IBaseRouteObjectLine;
                      if (!routeObject) {
                        return;
                      }
                      return (
                        <A4SubPage key={sh.id}>
                          <h5 className="mb-0 mt-2">
                            {sh.name} <strong>{formatDistance(routeObject.distance)}</strong>{' '}
                            <small>
                              {formattedLocaleTime(sh.start)} - {formattedLocaleTime(sh.finish)}
                            </small>
                          </h5>
                          <small className="d-block mb-2">
                            {routeObject.name}
                            {routeObject.description.length > 0 && (
                              <>
                                {' '}
                                • <em>{routeObject.description}</em>
                              </>
                            )}
                          </small>
                          <PolylineInfo
                            mapType={mapData}
                            name={routeObject.name}
                            points={routeObject.points}
                            height={allRo.length < 2 ? 860 : undefined}
                            poi={routeObjects.filter((p) => p.type === RouteObjectType.Point)}
                          />
                        </A4SubPage>
                      );
                    })}
                </A4SubPage>
              )}
              {dayData.transfers.length > 0 && (
                <HikingPrintTransfers transfers={dayData.transfers} />
              )}
            </A4SubPage>
          );
        })}
      </A4Page>

      {!!jointlyEquipment.filter((x) => x.type == 'tent').length && (
        <HikingPrintJointlyEquipment
          jointlyEquipment={jointlyEquipment.filter((x) => x.type == 'tent')}
          type="tent"
        />
      )}

      {!!jointlyEquipment.filter((x) => x.type == 'watercraft').length && (
        <HikingPrintJointlyEquipment
          jointlyEquipment={jointlyEquipment.filter((x) => x.type == 'watercraft')}
          type="watercraft"
        />
      )}

      <HikingPrintCommonEquipPage equip={hikingEquip} />
      <HikingPrintFirstAidKit hikingData={hikingData} />
      <HikingPrintRepairKit hikingData={hikingData} />
    </HikingContext.Provider>
  );
};

export default HikingPrint;
