import React from 'react';

import CloudLightning from '@pohodnik/icons/svg/Weather/CloudLightning';
import CloudLightningFill from '@pohodnik/icons/svg/Weather/CloudLightningFill';
import CloudRain from '@pohodnik/icons/svg/Weather/CloudRain';
import CloudRainFill from '@pohodnik/icons/svg/Weather/CloudRainFill';
import Clouds from '@pohodnik/icons/svg/Weather/Clouds';
import CloudsFill from '@pohodnik/icons/svg/Weather/CloudsFill';
import CloudSleet from '@pohodnik/icons/svg/Weather/CloudSleet';
import CloudSleetFill from '@pohodnik/icons/svg/Weather/CloudSleetFill';
import CloudSnow from '@pohodnik/icons/svg/Weather/CloudSnow';
import CloudSnowFill from '@pohodnik/icons/svg/Weather/CloudSnowFill';
import CloudSun from '@pohodnik/icons/svg/Weather/CloudSun';
import CloudSunFill from '@pohodnik/icons/svg/Weather/CloudSunFill';
import Cloudy from '@pohodnik/icons/svg/Weather/Cloudy';
import CloudyFill from '@pohodnik/icons/svg/Weather/CloudyFill';
import Sun from '@pohodnik/icons/svg/Weather/Sun';
import SunFill from '@pohodnik/icons/svg/Weather/SunFill';
import Sunrise from '@pohodnik/icons/svg/Weather/Sunrise';
import Sunset from '@pohodnik/icons/svg/Weather/Sunset';

import { IHikingWeather } from '@apps/Hiking/@types/hikingWeather.types';
import { round } from '@helpers/mathHelper';
import { degToCard } from '@helpers/weather.helper';

interface IHikingPrintWeatherProps extends React.HTMLAttributes<HTMLDivElement> {
  weather: IHikingWeather;
}

const iconsMap: Record<string, React.ReactElement<any>> = {
  '01n': <Sun />, // clear sky
  '02n': <CloudSun />, // few clouds
  '03n': <Cloudy />, // df
  '04n': <Clouds />, // broken clouds
  '09n': <CloudSleet />, // shower rain
  '10n': <CloudRain />, // rain
  '11n': <CloudLightning />, // thunderstorm
  '13n': <CloudSnow />, // snow
  '01d': <SunFill />, // clear sky
  '02d': <CloudSunFill />, // few clouds
  '03d': <CloudyFill />, // df
  '04d': <CloudsFill />, // broken clouds
  '09d': <CloudSleetFill />, // shower rain
  '10d': <CloudRainFill />, // rain
  '11d': <CloudLightningFill />, // thunderstorm
  '13d': <CloudSnowFill />, // snow
};

const HikingPrintWeather = ({ weather: currentWeather, ...rest }: IHikingPrintWeatherProps) => {
  return (
    <div {...rest}>
      <h4 className="mt-2">Метеорологические данные</h4>
      <Sunrise /> Рассвет:{' '}
      <small>{new Date(currentWeather.forecast.sunrise * 1e3).toUTCString()}</small>; <Sunset />{' '}
      Закат: <small>{new Date(currentWeather.forecast.sunset * 1e3).toUTCString()}</small>;{' '}
      Продолжительность светового дня:{' '}
      {new Date(
        currentWeather.forecast.sunset * 1e3 -
          currentWeather.forecast.sunrise * 1e3 +
          new Date().getTimezoneOffset() * 60 * 1000,
      )
        .toLocaleTimeString()
        .substr(0, 5)}
      {'. '}
      {iconsMap[currentWeather.forecast.weather[0].icon]}&nbsp; Прогноз погоды получен{' '}
      {currentWeather.created_at.toLocaleString()} для точки{' '}
      <a href={`geo:${currentWeather.lat},{currentWeather.lon}`}>
        {round(currentWeather.lat, 5)}, {round(currentWeather.lon, 5)}
      </a>{' '}
      ({currentWeather.name}). <b>{currentWeather.forecast.weather[0].description}</b>. Температура:{' '}
      <small className={'text-muted'}>Макс.</small>:&nbsp;
      {round(currentWeather.forecast.temp.max, 1)}°C; <small className="text-muted">Мин.</small>
      :&nbsp;
      {round(currentWeather.forecast.temp.min, 1)}°C;{' '}
      <small className={'text-muted'} title={`Ощущ: ${currentWeather.forecast.feels_like.night}`}>
        Ночью
      </small>
      :&nbsp;{round(currentWeather.forecast.temp.night, 1)}°C;{' '}
      <small className="text-muted" title={`Ощущ: ${currentWeather.forecast.feels_like.morn}`}>
        Утром
      </small>
      :&nbsp;{round(currentWeather.forecast.temp.morn, 1)}°C;{' '}
      <small className={'text-muted'} title={`Ощущ: ${currentWeather.forecast.feels_like.day}`}>
        Днем
      </small>
      :&nbsp;{round(currentWeather.forecast.temp.day, 1)}°C;{' '}
      <small className="text-muted" title={`Ощущ: ${currentWeather.forecast.feels_like.eve}`}>
        Вечером
      </small>
      :&nbsp;{round(currentWeather.forecast.temp.eve, 1)}°C;
      <br />
      Ветер: ({currentWeather.forecast.deg}°){' '}
      {currentWeather.forecast.deg ? degToCard(currentWeather.forecast.deg) : '-'}{' '}
      {round(currentWeather.forecast.speed, 1)}&nbsp;м/c,
      {currentWeather.forecast.gust > currentWeather.forecast.speed && (
        <span className="text-danger">
          {' '}
          с порывами до {round(currentWeather.forecast.gust, 0)}&nbsp;м/c
        </span>
      )}
      {'. '}
      {currentWeather.forecast.rain && currentWeather.forecast.pop > 0.09 && (
        <>
          Вероятность дождя {Math.floor(currentWeather.forecast.pop * 100)}%, (
          {round(currentWeather.forecast.rain, 0)}мм)
        </>
      )}{' '}
      {currentWeather.forecast.snow && currentWeather.forecast.pop > 0.09 && (
        <>
          Вероятность снега {Math.floor(currentWeather.forecast.pop * 100)}%, (
          {round(currentWeather.forecast.snow, 0) || '-'}мм)
        </>
      )}
      {'. '}
      Облачность: {currentWeather.forecast.clouds}%{'. '}
      Отн.&nbsp;влажность воздуха: {currentWeather.forecast.humidity}%{'. '}
      Атмосферное давление: {round(currentWeather.forecast.pressure * 0.75, 1)}
      мм.рт.ст ({currentWeather.forecast.pressure}гПа)
    </div>
  );
};

export default HikingPrintWeather;
